import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_conv_cuda = load_inline(
    name="custom_conv2d_cuda",
    cpp_sources=r"""
#include <torch/extension.h>

torch::Tensor conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("conv_forward", &conv_forward, "Custom CUDA Conv2d forward");
}
""",
    cuda_sources=r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

template <typename scalar_t, typename acc_t>
__global__ void conv2d_kernel(
    const scalar_t* __restrict__ input,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int N,
    int C,
    int H,
    int W,
    int K,
    int R,
    int S,
    int OH,
    int OW,
    int stride,
    int padding) {
    const int64_t total = static_cast<int64_t>(N) * K * OH * OW;

    for (int64_t linear = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
         linear < total;
         linear += static_cast<int64_t>(blockDim.x) * gridDim.x) {
        int64_t t = linear;

        const int ow = t % OW;
        t /= OW;
        const int oh = t % OH;
        t /= OH;
        const int k = t % K;
        const int n = t / K;

        acc_t sum = static_cast<acc_t>(bias[k]);

        for (int c = 0; c < C; ++c) {
            for (int r = 0; r < R; ++r) {
                const int ih = oh * stride - padding + r;
                if (ih < 0 || ih >= H) {
                    continue;
                }

                for (int s = 0; s < S; ++s) {
                    const int iw = ow * stride - padding + s;
                    if (iw < 0 || iw >= W) {
                        continue;
                    }

                    const int64_t input_index =
                        ((static_cast<int64_t>(n) * C + c) * H + ih) * W + iw;
                    const int64_t weight_index =
                        ((static_cast<int64_t>(k) * C + c) * R + r) * S + s;

                    sum += static_cast<acc_t>(input[input_index]) *
                           static_cast<acc_t>(weight[weight_index]);
                }
            }
        }

        output[linear] = static_cast<scalar_t>(sum);
    }
}

torch::Tensor conv_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");

    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be KCRS");
    TORCH_CHECK(bias.dim() == 1, "bias must be 1D");

    TORCH_CHECK(input.scalar_type() == weight.scalar_type(),
                "input and weight must have the same dtype");
    TORCH_CHECK(input.scalar_type() == bias.scalar_type(),
                "input and bias must have the same dtype");

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();

    const int N = static_cast<int>(input_c.size(0));
    const int C = static_cast<int>(input_c.size(1));
    const int H = static_cast<int>(input_c.size(2));
    const int W = static_cast<int>(input_c.size(3));

    const int K = static_cast<int>(weight_c.size(0));
    const int weight_C = static_cast<int>(weight_c.size(1));
    const int R = static_cast<int>(weight_c.size(2));
    const int S = static_cast<int>(weight_c.size(3));

    TORCH_CHECK(weight_C == C, "weight channel dimension mismatch");
    TORCH_CHECK(bias_c.size(0) == K, "bias dimension mismatch");

    constexpr int stride = 4;
    constexpr int padding = 2;

    const int OH = (H + 2 * padding - R) / stride + 1;
    const int OW = (W + 2 * padding - S) / stride + 1;

    auto output = torch::empty(
        {N, K, OH, OW},
        input_c.options());

    const int64_t total = static_cast<int64_t>(N) * K * OH * OW;
    constexpr int threads = 256;
    const int blocks = static_cast<int>(
        std::min<int64_t>((total + threads - 1) / threads, 4096));

    cudaStream_t stream =
        at::cuda::getCurrentCUDAStream(input_c.get_device()).stream();

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        input_c.scalar_type(),
        "custom_conv2d_cuda",
        [&] {
            using acc_t = at::acc_type<scalar_t, true>;

            conv2d_kernel<scalar_t, acc_t>
                <<<blocks, threads, 0, stream>>>(
                    input_c.data_ptr<scalar_t>(),
                    weight_c.data_ptr<scalar_t>(),
                    bias_c.data_ptr<scalar_t>(),
                    output.data_ptr<scalar_t>(),
                    N,
                    C,
                    H,
                    W,
                    K,
                    R,
                    S,
                    OH,
                    OW,
                    stride,
                    padding);
        });

    return output;
}
""",
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3,
            out_channels=96,
            kernel_size=11,
            stride=4,
            padding=2,
        )

    def forward(self, x):
        return _conv_cuda.conv_forward(
            x,
            self.conv1.weight,
            self.conv1.bias,
        )

